// Extract incoming BizPilot AI customer & campaign data
const input = $input.item.json.body;
const customer = input.customer || {};
const campaign = input.campaign || {};

const firstName = customer.name ? customer.name.split(' ')[0] : 'Valued Customer';
const segment = customer.segment || 'Standard';
const incentiveCode = campaign.incentiveCode || 'VIP-SAVE15';
const incentiveDesc = campaign.incentiveDesc || '15% Off Your Next Restock';
const churnRisk = customer.churnRisk || 75;
const recencyDays = customer.recencyDays || 45;
const rawBody = campaign.body || '';

// Generate responsive, branded HTML email template
const htmlBody = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #0f172a; color: #e2e8f0; margin: 0; padding: 24px; }
    .container { max-width: 580px; margin: 0 auto; background: #1e293b; border-radius: 16px; border: 1px solid #334155; overflow: hidden; box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5); }
    .header { background: linear-gradient(135deg, #6366f1 0%, #4f46e5 100%); padding: 32px 24px; text-align: center; color: #ffffff; }
    .header h1 { margin: 0; font-size: 24px; font-weight: 700; letter-spacing: -0.5px; }
    .header p { margin: 6px 0 0 0; opacity: 0.85; font-size: 14px; }
    .content { padding: 28px 24px; font-size: 14px; line-height: 1.6; color: #cbd5e1; }
    .voucher-box { background: #0f172a; border: 1px dashed #6366f1; border-radius: 12px; padding: 20px; text-align: center; margin: 24px 0; }
    .voucher-code { font-family: monospace; font-size: 22px; font-weight: bold; color: #818cf8; letter-spacing: 2px; background: #1e1b4b; padding: 8px 16px; border-radius: 8px; display: inline-block; margin-top: 8px; }
    .footer { background: #0f172a; border-top: 1px solid #334155; padding: 18px 24px; text-align: center; font-size: 12px; color: #64748b; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>BizPilot AI</h1>
      <p>Exclusive Customer Appreciation & Win-Back Offer</p>
    </div>
    <div class="content">
      <p>Hello <strong>${customer.name}</strong>,</p>
      <p>${rawBody.replace(/\n/g, '<br>')}</p>

      <div class="voucher-box">
        <div style="font-size: 13px; color: #94a3b8;">YOUR EXCLUSIVE ${segment.toUpperCase()} INCENTIVE</div>
        <div style="font-size: 15px; color: #ffffff; font-weight: 600; margin-top: 4px;">${incentiveDesc}</div>
        <div class="voucher-code">${incentiveCode}</div>
      </div>

      <p style="font-size: 12px; color: #94a3b8;">
        * Automatically calibrated by BizPilot AI Retention Intelligence (RandomForest Churn Assessment: ${churnRisk}% risk, ${recencyDays}d inactivity interval).
      </p>
    </div>
    <div class="footer">
      &copy; 2026 BizPilot AI Platform • Autonomous Enterprise Operations
    </div>
  </div>
</body>
</html>
`;

return {
  json: {
    recipientEmail: customer.email,
    recipientName: customer.name,
    subject: campaign.subject || `Special Retention Offer for ${customer.name}`,
    htmlBody,
    incentiveCode,
    churnRisk,
    deliveredVia: 'n8n_workflow_engine',
    timestamp: new Date().toISOString()
  }
};
